304	// parseInterfaces parses a armnetwork.Interface as returned by the Azure API
305	// converts it into a types.AzureInterface
306	func parseInterface(iface *armnetwork.Interface, subnets ipamTypes.SubnetMap, usePrimary bool) (instanceID string, i *types.AzureInterface) {
307		i = &types.AzureInterface{}
308	
309		if iface.Properties.VirtualMachine != nil && iface.Properties.VirtualMachine.ID != nil {
310			instanceID = strings.ToLower(*iface.Properties.VirtualMachine.ID)
311		}
312	
313		if iface.Properties.MacAddress != nil {
314			// Azure API reports MAC addresses as AA-BB-CC-DD-EE-FF
315			i.MAC = strings.ReplaceAll(*iface.Properties.MacAddress, "-", ":")
316		}
317	
318		if iface.ID != nil {
319			i.SetID(*iface.ID)
320		}
321	
322		if iface.Name != nil {
323			i.Name = *iface.Name
324		}
325	
326		if iface.Properties.NetworkSecurityGroup != nil {
327			if iface.Properties.NetworkSecurityGroup.ID != nil {
328				i.SecurityGroup = *iface.Properties.NetworkSecurityGroup.ID
329			}
330		}
331	
332		if iface.Properties.IPConfigurations != nil {
333			for _, ip := range iface.Properties.IPConfigurations {
334				if ip.Properties.PrivateIPAddress == nil {
335					continue
336				}
337				isPrimary := ip.Properties.Primary != nil && *ip.Properties.Primary
338				if isPrimary {
339					i.IP = *ip.Properties.PrivateIPAddress
340					if !usePrimary {
341						continue
342					}
343				}
344	
345				addr := types.AzureAddress{
346					IP:    *ip.Properties.PrivateIPAddress,
347					State: strings.ToLower(string(*ip.Properties.ProvisioningState)),
348				}
349	
350				if ip.Properties.Subnet != nil {
351					addr.Subnet = *ip.Properties.Subnet.ID
352					if subnet, ok := subnets[addr.Subnet]; ok {
353						if subnet.CIDR.IsValid() {
354							i.CIDR = subnet.CIDR.String()
355						}
356						i.Gateway = deriveGatewayIP(subnet.CIDR.Addr())
357					}
358				}
359	
360				i.Addresses = append(i.Addresses, addr)
361			}
362		}
363	
364		return
365	}
